INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 16, 'theory', 'Quiz: CSS selectors, states and specificity');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 0, 'What will the browser do if one declaration in a rule has a typo in the property name?', '["Drop the whole rule", "Drop only that declaration, and the others keep working", "Stop rendering and show an error message", "Ignore the entire stylesheet"]', 1, 'CSS parsing forgives errors: an invalid declaration is silently dropped and its neighbors work. A broken selector is worse: it kills the whole rule. So "nothing changed" is a reason to look in the developer tools.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 1, 'What does the selector .menu > li pick?', '["Only li items that are direct children of an element with the class menu", "All li items at any depth inside .menu", "li items standing right after .menu", "The .menu elements that contain an li"]', 0, 'The greater-than sign means a direct child. For any depth use a space, for the next sibling a plus, and picking by content is :has.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 2, 'Which rule wins: "#nav a" or ".menu .item a.link"?', '["The second: it has more classes", "The one written lower in the file", "They are equal, because both have the type a", "The first: one id outweighs any number of classes"]', 3, 'Specificity is a triple (ids, classes, types) compared left to right: the first selector has (1, 0, 1), the second (0, 3, 1). The order in the file decides only on a complete tie.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 3, 'How does :where() differ from :is()?', '["Only :where accepts several selectors", "Only :is works with classes", "The specificity of :where is always zero, while :is takes the heaviest argument", "They do not differ at all"]', 2, 'The same elements match, but the weight differs. The zero specificity of :where suits base styles that any rule can easily override.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 4, 'What are ::before and ::after with the content property good for?', '["Important text that a screen reader must read", "Decorations: arrows, icons, underlines", "Content that a search engine will index", "Replacing real markup elements, such as buttons"]', 1, 'Content from CSS is not part of the markup: it may go unread, unfound and unselectable. Meaning must live in HTML, and pseudo-elements remain decoration.');
